                    hist[maxBucketVal]--;
                    hist[diffVal]++;
                    total += diffVal;
                } else if (total < maxB) {
                    total += diffVal;
                    hist[diffVal]++;
                    totalSegments++;
                    startIdx = i + 1;
                }
                if (i == data.length - 2 && index < data.length - 1) {
