#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int findMaxBucket(const std::vector<int>& buckets) {
    for (int i = buckets.size() - 1; i >= 0; i--) {
        if (buckets[i] > 0) {
            return i;
        }
    }
    return -1;
}

int main() {
    int size, maxB;
    std::cin >> size >> maxB;
    std::vector<int> data(size);
    for (int j = 0; j < size; j++) {
        std::cin >> data[j];
    }

    std::vector<int> hist(101, 0);
    int total = 0;

    int evenCount = 0;
    int oddCount = 0;
    int startIdx = 0;
    int totalSegments = 0;
    int index = 1;

    for (int i = 0; i < static_cast<int>(data.size()) - 1; i++) {
        if (data[i] % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }

        if (evenCount == oddCount) {
            int diffVal = std::abs(data[i + 1] - data[i]);
            int maxBucketVal = findMaxBucket(hist);
            if (total > maxB && diffVal < maxBucketVal) {
                total -= maxBucketVal;
                hist[maxBucketVal]--;
                hist[diffVal]++;
                total += diffVal;
            } else if (total < maxB) {
                total += diffVal;
                hist[diffVal]++;
                totalSegments++;
                startIdx = i + 1;
            }
            if (i == static_cast<int>(data.size()) - 2 && index < static_cast<int>(data.size()) - 1) {
                i = startIdx++;
                evenCount = 0;
                oddCount = 0;
            }
        }
    }

    int i = static_cast<int>(hist.size()) - 1;
    while (total > maxB && i >= 0) {
        if (hist[i] > 0) {
            total -= i;
            hist[i]--;
            if (total <= maxB) break;
        } else {
            i--;
        }
    }

    std::cout << totalSegments << std::endl;
    return 0;
}
